---@class UIBattleBuffMgr
local UIBattleBuffMgr = {}

---@class RoleBuffVo
local RoleBuffVo = {}
function RoleBuffVo.New(Id, buffId, targetId, layNum, buffLB, star, lv)
    local this = {}
    setmetatable(this, { __index = RoleBuffVo })
    this.mainId = Id
    this.BuffId = buffId
    this.targetId = targetId
    this.layNum = layNum
    this.star = star
    this.lv = lv
    this.luaBehaviour = buffLB
    return this
end

------------ lifeCycle ------------

function UIBattleBuffMgr:Init()
    self.listRoleBuffs = nil
    self.listRoleBuffs = {}
end

function UIBattleBuffMgr:Delete()
    self.listRoleBuffs = nil
end

------------ lifeCycle ------------

------------ GetData ------------

function UIBattleBuffMgr:GetBuff(pUID)
    for i, buffData in ipairs(self.listRoleBuffs) do
        local uid = buffData.mainId
        if uid == pUID then
            return buffData, i
        end
    end
end

function UIBattleBuffMgr:GetRoleBuffList(roleId)
    local buffsList = {}
    for i, buffVo in ipairs(self.listRoleBuffs) do
        if buffVo.targetId == roleId then
            table.insert(buffsList, buffVo)
        end
    end
    return buffsList
end

