------------ ActionOnBuffsChange ------------  

function UIBattleBuffMgr:ActionOnAddBuff(buffMainId, buffTypeId, buffTargetId, buffLayer, buffIconLB)
    if isNull(self.listRoleBuffs) then
        self.listRoleBuffs = {}
    end
    local _isContain = function(id)
        for i, buffData in pairs(self.listRoleBuffs) do
            if checkNumber(buffData.mainId) == checkNumber(id) then
                return true
            end
        end
        return false
    end
    if not _isContain(buffMainId) then
        table.insert(self.listRoleBuffs ,RoleBuffVo.New(buffMainId, buffTypeId, buffTargetId, buffLayer, buffIconLB))
    end
end

function UIBattleBuffMgr:ActionOnChangeBuff(data)
    local uid  = checkInt(data.uid)
    local buffData = self:GetBuff(uid)
    if buffData then
        if not IsNull(buffData.luaBehaviour) then
            local buffRemainNum = data.remain -- Buff 剩余回合数
            local buffLayer = data.lay -- buff 层数
            local lbBuffNode = buffData.luaBehaviour
            local ltBuffNode = lbBuffNode.Env
            ltBuffNode:SetNodeTxt(buffRemainNum, buffLayer)
        end
        buffData.layNum = data.lay
    end
end

function UIBattleBuffMgr:ActionOnRemoveBuff(data)
    local uid  = checkInt(data.uid)
    local buffData, index = self:GetBuff(uid)
    if buffData then
        if not IsNull(buffData.luaBehaviour) then
            local lbBuffNode = buffData.luaBehaviour
            local ltBuffNode = lbBuffNode.Env
            ltBuffNode:RecycleBuffNode()
            self:RMBuffDataByIndex(index)
        end
    end
end

------------ ActionOnBuffsChange ------------  

function UIBattleBuffMgr:ListBuffNodesSyncTxtPos(roleId)
    local roleBuffsList = self:GetRoleBuffList(roleId)
    for i, v in ipairs(roleBuffsList) do
        local buffNodeLB = v.luaBehaviour
        if not IsNull(buffNodeLB) then
            buffNodeLB.Env:SynBuffTxtPos()
        end
    end
end

function UIBattleBuffMgr:RMBuffDataByIndex(index)
    if self.listRoleBuffs[index] then
        table.remove(self.listRoleBuffs, index)
    end
end

function UIBattleBuffMgr:RMBuffDataByUID(uid)
    local _GetRoleBuff = function(pUID)
        for index, buffData in pairs(self.listRoleBuffs) do
            if pUID == buffData.mainId then
                return buffData,index
            end
        end
    end
    local data, index = _GetRoleBuff(uid)
    if index then
        self:RMBuffDataByIndex(index)
    end
end

function UIBattleBuffMgr:CleanListBuffNode(roleId)
    local listBuffs = self:GetRoleBuffList(roleId)
    for i, buffData in pairs(listBuffs) do
        local ltBuff = buffData.luaBehaviour.Env
        ltBuff:RecycleBuffNode()
        local buffUID = buffData.mainId
        self:RMBuffDataByUID(buffUID)
    end
end

return UIBattleBuffMgr